/**
 * Generates public/firebase-messaging-sw.js from Vite env vars.
 * Service workers cannot read import.meta.env — values are injected at build/dev time.
 * The generated file is gitignored; never commit real keys.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, '..');
const outPath = resolve(root, 'public', 'firebase-messaging-sw.js');

const ENV_KEYS = [
  'VITE_FIREBASE_API_KEY',
  'VITE_FIREBASE_AUTH_DOMAIN',
  'VITE_FIREBASE_PROJECT_ID',
  'VITE_FIREBASE_STORAGE_BUCKET',
  'VITE_FIREBASE_MESSAGING_SENDER_ID',
  'VITE_FIREBASE_APP_ID',
];

const loadEnvFile = () => {
  const envPath = resolve(root, '.env');
  const values = {};

  if (!existsSync(envPath)) {
    return values;
  }

  for (const line of readFileSync(envPath, 'utf8').split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    let value = trimmed.slice(eq + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    values[key] = value;
  }

  return values;
};

const env = { ...loadEnvFile(), ...process.env };
const missing = ENV_KEYS.filter((key) => !env[key]);

if (missing.length > 0) {
  console.warn(
    `[firebase-sw] Skipping generation — missing env: ${missing.join(', ')}. ` +
      'Copy .env.example to .env and set Firebase values for push notifications.',
  );

  const stub = `/* Generated stub — configure VITE_FIREBASE_* in .env and run npm run generate:firebase-sw */
self.addEventListener('push', () => {});
`;
  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, stub, 'utf8');
  process.exit(0);
}

const escape = (value) => JSON.stringify(value);

const contents = `/**
 * AUTO-GENERATED by scripts/generate-firebase-sw.mjs — DO NOT EDIT OR COMMIT.
 * Regenerate: npm run generate:firebase-sw (runs before dev/build).
 * Service workers cannot read Vite env vars at runtime.
 */
/* eslint-disable no-undef */
importScripts('https://www.gstatic.com/firebasejs/10.12.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.12.0/firebase-messaging-compat.js');

firebase.initializeApp({
  apiKey: ${escape(env.VITE_FIREBASE_API_KEY)},
  authDomain: ${escape(env.VITE_FIREBASE_AUTH_DOMAIN)},
  projectId: ${escape(env.VITE_FIREBASE_PROJECT_ID)},
  storageBucket: ${escape(env.VITE_FIREBASE_STORAGE_BUCKET)},
  messagingSenderId: ${escape(env.VITE_FIREBASE_MESSAGING_SENDER_ID)},
  appId: ${escape(env.VITE_FIREBASE_APP_ID)},
});

const messaging = firebase.messaging();

messaging.onBackgroundMessage((payload) => {
  const title = payload.notification?.title ?? 'Observerr';
  const body = payload.notification?.body ?? 'You have a new notification';

  self.registration.showNotification(title, {
    body,
    icon: '/observerr-logo.png',
    badge: '/observerr-logo.png',
    data: payload.data,
  });
});
`;

mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, contents, 'utf8');
console.log('[firebase-sw] Wrote public/firebase-messaging-sw.js');
